def get_number():
    """Get a valid number from user input."""
    while True:
        try:
            num = float(input("Enter a number: "))
            return num
        except ValueError:
            print("That's not a valid number. Please try again.")

def get_operator():
    """Get a valid operator from user input."""
    operators = {"+": add, "-": subtract, "*": multiply, "/": divide}
    while True:
        operator = input("Enter an operator (+, -, *, /): ").upper()
        if operator in operators:
            return operator, operators[operator]
        print("That's not a valid operator. Please try again.")

def perform_operation(num1, num2, operation):
    """Perform the given operation on two numbers and return the result."""
    return operation(num1, num2)

def add(num1, num2):
    """Perform addition on two numbers."""
    return num1 + num2

def subtract(num1, num2):
    """Perform subtraction on two numbers."""
    return num1 - num2

def multiply(num1, num2):
    """Perform multiplication on two numbers."""
    return num1 * num2

def divide(num1, num2):
    """Perform division on two numbers, handling division by zero."""
    if num2 == 0:
        print("Error: Division by zero is not allowed.")
        return None
    return num1 / num2

if __name__ == "__main__":
    num1 = get_number()
    operator, operation = get_operator()
    num2 = get_number()

    result = perform_operation(num1, num2, operation)

    if result is not None:
        print(f"{num1} {operator} {num2} = {result}")
